def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    bg = max(counts, key=counts.get)

    # Find diagonal runs of at least two matching, nonzero cells, then extend
    # their ends through the background.
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg or color == 0:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue  # not the start of this run

                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) < 2:
                    continue

                for sr, sc, step_r, step_c in (
                    (run[0][0], run[0][1], -dr, -dc),
                    (run[-1][0], run[-1][1], dr, dc),
                ):
                    rr, cc = sr + step_r, sc + step_c
                    while (0 <= rr < h and 0 <= cc < w and
                           grid[rr][cc] == bg):
                        out[rr][cc] = color
                        rr += step_r
                        cc += step_c

    return out
